import zipfile, re
fin = zipfile.ZipFile('3_59340_answer_template_5277_final.xlsx')
s = fin.read('xl/worksheets/sheet1.xml').decode()
# print the O2 cell
print('O2 cell:', re.search(r'<c r="O2".*?</c>', s).group(0))
# compare filled values against golden
golden = zipfile.ZipFile('/mnt/hhq/data/data_pipeline/generated_tasks/route_b_answer_files_batch1/passed/template/3_59340_answer_template_5277_golden.xlsx')
gs = golden.read('xl/worksheets/sheet1.xml').decode()
gvals={}
for m in re.finditer(r'<c r="([A-Z]+\d+)"[^>]*?(?:/>|>(.*?)</c>)', gs, re.S):
    coord, inner = m.group(1), m.group(2)
    if inner is not None:
        vm = re.search(r'<v>(.*?)</v>', inner)
        if vm:
            gvals[coord]=vm.group(1)
fvals={}
for m in re.finditer(r'<c r="([A-Z]+\d+)"[^>]*?(?:/>|>(.*?)</c>)', s, re.S):
    coord, inner = m.group(1), m.group(2)
    if inner is not None:
        vm = re.search(r'<v>(.*?)</v>', inner)
        if vm:
            fvals[coord]=vm.group(1)
missing=[]
for c,v in gvals.items():
    if c=='O2':
        continue
    if fvals.get(c) != v:
        missing.append((c, v, fvals.get(c)))
print('mismatches:', missing)
print('golden data count', len(gvals), 'final data count', len(fvals))
